const DAY_MAP: Record<number, PracticeQ[]> = {
  22: ALL_DAY_22_QUESTIONS,
  23: ALL_DAY_23_QUESTIONS,
  24: ALL_DAY_24_QUESTIONS,
  25: ALL_DAY_25_QUESTIONS,
  26: ALL_DAY_26_QUESTIONS,
  27: ALL_DAY_27_QUESTIONS,
  28: ALL_DAY_28_QUESTIONS,
};

/**
 * Returns hand-crafted questions for Days 22-28.
 * Optionally filters by subtopicId.
 */
export function getDays22to28Questions(
  dayNumber: number,
  subtopicId?: string
): PracticeQ[] {
  const all = DAY_MAP[dayNumber] ?? [];
  if (!subtopicId) return all;
  const filtered = all.filter((q) => q.subtopicId === subtopicId);
  return filtered.length > 0 ? filtered : all;
}
